    s = surface_clear(s, color_black())
    s = surface_set_pixel(s, 0, 0, Color { r: 255, g: 0, b: 0, a: 128 })
    s = surface_set_pixel(s, 1, 0, Color { r: 0, g: 255, b: 0, a: 255 })
